{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C01","C05","C08","C12","C231","C204","C219","C221","C226","C229","C235","C236","C243","C155","C158","C189"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C01","C05","C08","C12","C231"],
  "claims": [
    {
      "claim": "The query is ibrutinib; no direct F measurement is supplied. Transferable L1 gold low-F contexts (FK3453, danavorexton, astemizole) provide affirmative analogical evidence for F < 20% via presystemic/first-pass elimination, despite structural differences.",
      "card_ids": ["C01","C05","C08","C12"]
    },
    {
      "claim": "L6 C231 directly identifies ibrutinib among drugs for which hepatic metabolism via CYPs is the major route of elimination, providing query-relevant mechanistic support for first-pass hepatic loss.",
      "card_ids": ["C231"]
    },
    {
      "claim": "Related BTK inhibitors (zanubrutinib, acalabrutinib, remibrutinib) are predominantly CYP3A-metabolized with high hepatic intrinsic clearance, supporting a class-level first-pass liability; these are mechanistic records, not direct F results.",
      "card_ids": ["C204","C219","C221","C226","C229","C235","C236","C243"]
    },
    {
      "claim": "Close ibrutinib analogs show high Caco-2 permeability and no appreciable efflux, so absorption is unlikely to be the main limiter; the low-F direction is better explained by first-pass metabolism.",
      "card_ids": ["C155","C158","C189"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C231","C204","C219","C221","C226","C229","C235","C236","C243"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for ibrutinib in the supplied records.",
    "C231 is qualitative; no query-specific hepatic extraction ratio, clearance value, or F value is provided.",
    "L1 low-F contexts are structurally distinct from ibrutinib; transferability is analogical.",
    "No query-specific solubility, permeability, efflux, or intestinal metabolism data; L4/L5 records are for analogs.",
    "L6 intrinsic clearance values are mostly for other BTK inhibitors and in vitro assays; species/assay translation is uncertain."
  ],
  "decision_summary": "The query is ibrutinib. No direct F measurement is supplied, but L6 C231 directly states that hepatic CYP metabolism is the major elimination route for ibrutinib, providing query-relevant mechanistic support for first-pass loss. Combined with transferable L1 low-F gold contexts and class-level CYP3A metabolism of related BTK inhibitors, the affirmative evidence supports F < 20%; the prediction remains low with moderate confidence."
}

